import{_ as e,o as s,c as n,a0 as t}from"./chunks/framework.bcCluOOn.js";const h=JSON.parse('{"title":"AAYU Language","description":"","frontmatter":{},"headers":[],"relativePath":"platform/language.md","filePath":"platform/language.md"}'),i={name:"platform/language.md"};function o(l,a,r,p,c,d){return s(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="aayu-language" tabindex="-1">AAYU Language <a class="header-anchor" href="#aayu-language" aria-label="Permalink to &quot;AAYU Language&quot;">​</a></h1><p><strong>Status: Developer Preview</strong></p><p>AAYU Language is a clean, minimal, and strict programming language designed specifically for generating software architectures.</p><h2 id="the-aayu-difference" tabindex="-1">The AAYU Difference <a class="header-anchor" href="#the-aayu-difference" aria-label="Permalink to &quot;The AAYU Difference&quot;">​</a></h2><p>Traditional languages focus on algorithms and memory management. AAYU focuses on <strong>Architecture, Intents, and Entities</strong>.</p><p>By writing <code>.aayu</code> files, you are writing a blueprint. The AAYU Engine parses this blueprint and generates the actual low-level React, FastAPI, and Postgres code.</p><h2 id="language-features" tabindex="-1">Language Features <a class="header-anchor" href="#language-features" aria-label="Permalink to &quot;Language Features&quot;">​</a></h2><h3 id="use-imports" tabindex="-1"><code>use</code> (Imports) <a class="header-anchor" href="#use-imports" aria-label="Permalink to &quot;\`use\` (Imports)&quot;">​</a></h3><p>Define which domains your software relies on.</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use http.</span></span>
<span class="line"><span>use db.</span></span></code></pre></div><h3 id="record-entities" tabindex="-1"><code>record</code> (Entities) <a class="header-anchor" href="#record-entities" aria-label="Permalink to &quot;\`record\` (Entities)&quot;">​</a></h3><p>Define your database tables or core business models.</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>record Patient.</span></span>
<span class="line"><span>    name</span></span>
<span class="line"><span>    phone</span></span>
<span class="line"><span>end.</span></span></code></pre></div><h3 id="task-workflows" tabindex="-1"><code>task</code> (Workflows) <a class="header-anchor" href="#task-workflows" aria-label="Permalink to &quot;\`task\` (Workflows)&quot;">​</a></h3><p>Define server logic, UI interactions, or background jobs.</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>task setup_dashboard.</span></span>
<span class="line"><span>    show &quot;Hospital&quot;.</span></span>
<span class="line"><span>    show &quot;Welcome Patient&quot;.</span></span>
<span class="line"><span>end.</span></span></code></pre></div><h3 id="if-repeat-control-flow" tabindex="-1"><code>if</code> &amp; <code>repeat</code> (Control Flow) <a class="header-anchor" href="#if-repeat-control-flow" aria-label="Permalink to &quot;\`if\` &amp; \`repeat\` (Control Flow)&quot;">​</a></h3><p>(Experimental - Available in Runtime Track B)</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if age greater than 18.</span></span>
<span class="line"><span>    show &quot;Adult&quot;.</span></span>
<span class="line"><span>end.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>repeat 5 times.</span></span>
<span class="line"><span>    show &quot;Hello&quot;.</span></span>
<span class="line"><span>end.</span></span></code></pre></div><h2 id="runtime-roadmap" tabindex="-1">Runtime Roadmap <a class="header-anchor" href="#runtime-roadmap" aria-label="Permalink to &quot;Runtime Roadmap&quot;">​</a></h2><p>While Track A focuses on generating code (Software Factory), Track B is building an <strong>Experimental Stack VM Runtime (AYC)</strong> that executes <code>.aayu</code> directly.</p><ul><li>[x] Print / Show</li><li>[x] Variable Declarations</li><li>[x] Basic Math</li><li>[x] If Conditions</li><li>[ ] Loops (<code>repeat</code>, <code>for each</code>)</li><li>[ ] Function / Task Execution</li></ul>`,22)])])}const g=e(i,[["render",o]]);export{h as __pageData,g as default};
